def minimax(leaves, maximize=True):
    if not leaves:
        raise ValueError("provide at least one leaf")
    if len(leaves) == 1:
        return leaves[0]
    middle = len(leaves) // 2
    choices = (minimax(leaves[:middle], not maximize),
               minimax(leaves[middle:], not maximize))
