fun findSorted(values: IntArray, target: Int): Int {
    var start = 0
    var end = values.size
    while (start < end) {
        val mid = start + (end - start) / 2
        when {
            values[mid] < target -> start = mid + 1
            values[mid] > target -> end = mid
            else -> return mid
        }
    }
    return -1
}

