fun insertionSort(a: IntArray) {
    for (i in 1 until a.size) {
        val item = a[i]
        var j = i
        while (j > 0 && a[j - 1] > item) {
            a[j] = a[j - 1]
            j--
        }
        a[j] = item
    }
}

